// AssertContractContract runs every generated check against every declared subject.
//
//	Subjects: declare each with ContractSubject
//	Extend:   ContractOnLookup, ContractOnFetch
//	Drop:     ContractWithout, by the path each check reports under
//	Unseeded: every check here runs against a fresh subject, because
//	          no method here is classified as a write.
//	          A read over an empty subject cannot tell a miss from a bug;
//	          ContractSeed is what closes it.
func AssertContractContract(t *testing.T, opts ...ContractOption) {
	t.Helper()
	cfg := newContractConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertContractContract was given no subject; declare one with " +
			"ContractSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("ContractWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runContractChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runContractChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runContractChecks(
	t *testing.T,
	cfg *contractConfig,
	label string,
	factory func() cache.Contract,
	wrap func(tb testing.TB, subject cache.Contract) cache.Contract,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(contractLookup, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onLookup {
				cfg.run(t, string(suite.MethodID(contractLookup, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
				})
			}
		})

		t.Run(contractFetch, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onFetch {
				cfg.run(t, string(suite.MethodID(contractFetch, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through ContractWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

// ContractOption configures a contract run.
type ContractOption func(*contractConfig)

// ContractSubject declares an implementation to hold to the contract.
//
// Repeat it for every implementation that claims to satisfy the interface — an
// in-memory one, the one backed by a database, the one behind a network. Every
// check and every option is stated once and runs against all of them, which is
// what a conformance suite is for.
func ContractSubject(name string, factory func() cache.Contract) ContractOption {
	return func(c *contractConfig) {
		c.subjects = append(c.subjects, namedContractSubject{name, factory})
	}
}

// ContractWithClock supplies the clock every time-reading check measures on.
//
// Defaults to the real one, so an implementation that does not take a clock
// behaves as it would have. Supply a [clock.TestClock] — the same one the
// factory builds the subject with — and a budget becomes a claim about the time
// the implementation means to spend rather than about how loaded the machine
// was.
func ContractWithClock(c clock.Clock) ContractOption {
	return func(cfg *contractConfig) { cfg.clock = c }
}

// ContractWithFixture replaces the derived inputs.
func ContractWithFixture(f ContractFixture) ContractOption {
	return func(c *contractConfig) { c.Fixture = f }
}

// ContractSeed replaces the derived seed.
//
// For an interface with no writer to seed itself through, which is the one
// input a conformance run cannot derive: a reader over an empty subject
// asserts nothing.
//
// Returning an error rather than swallowing one. A seed that failed quietly
// leaves every check after it asserting nothing and reporting success.
func ContractSeed(fn func(ctx context.Context, subject cache.Contract) error) ContractOption {
	return func(c *contractConfig) {
		c.seed = fn
	}
}

// ContractOnLookup adds a named check to Lookup.
func ContractOnLookup(name string, fn ContractLookupCheck) ContractOption {
	return func(c *contractConfig) {
		c.onLookup = append(c.onLookup, namedContractLookupCheck{name, fn})
	}
}

// ContractOnFetch adds a named check to Fetch.
func ContractOnFetch(name string, fn ContractFetchCheck) ContractOption {
	return func(c *contractConfig) {
		c.onFetch = append(c.onFetch, namedContractFetchCheck{name, fn})
	}
}

// ContractWithout drops generated checks by the path each reports under.
//
// For a subject that legitimately violates one. Without this the only recourse
// is to stop running the suite, which costs every other check in the file — so
// a dropped check is reported as skipped rather than silently omitted.
func ContractWithout(paths ...string) ContractOption {
	return func(c *contractConfig) {
		for _, p := range paths {
			c.without[p] = struct{}{}
		}
	}
}

type namedContractLookupCheck struct {
	name string
	fn   ContractLookupCheck
}

type namedContractFetchCheck struct {
	name string
	fn   ContractFetchCheck
}

type namedContractSubject struct {
	name    string
	factory func() cache.Contract
}

// contractContractExtension is a body of checks a generated sibling adds through an option.
//
// A sibling declares the option and closes over whatever configures it, so
// everything that varies per run is typed and private to the file that owns it
// — this file understands only the name and the call. Nothing arrives except
// through an option, which is what keeps the set fixed before the first subtest
// starts.
type contractContractExtension struct {
	// name is the path this reports under, and the one ContractWithout drops
	// it by. Anything nested beneath it is the extension's own to name.
	name string

	// run takes the factory rather than a subject. One that drives sequences
	// builds a subject per iteration, and one that compares against a reference
	// needs the unseeded subject a factory returns — which
	// contractConfig.subject is not.
	//
	// Called once per subject, in parallel, sharing the config. Anything it
	// mutates has to be built inside the call: state captured when the option
	// was declared is state two subjects write at once.
	run func(
		t *testing.T,
		subject string,
		factory func() cache.Contract,
		cfg *contractConfig,
	)
}

type contractConfig struct {
	Fixture    ContractFixture
	subjects   []namedContractSubject
	clock      clock.Clock
	seed       func(ctx context.Context, subject cache.Contract) error
	without    map[string]struct{}
	extensions []contractContractExtension
	onLookup   []namedContractLookupCheck
	onFetch    []namedContractFetchCheck
}

func newContractConfig(opts ...ContractOption) *contractConfig {
	c := &contractConfig{
		Fixture: DefaultContractFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	for _, o := range opts {
		o(c)
	}
	return c
}

// subject builds a fresh implementation and seeds it, so every check runs
// against state no other check touched.
func (c *contractConfig) subject(
	tb testing.TB,
	factory func() cache.Contract,
	wrap func(tb testing.TB, subject cache.Contract) cache.Contract,
) cache.Contract {
	tb.Helper()
	s := factory()
	if c.seed != nil {
		// Reported rather than ignored. A seed that silently failed would leave
		// every check after it running against an empty subject — passing, and
		// asserting nothing.
		//
		// Which seed ran decides what the message can usefully say. The derived
		// one fails for one of two reasons and both are fixable from here, so it
		// names them. A seed the caller supplied is theirs, and telling them to
		// supply one is advice they already took.
		if err := c.seed(tb.Context(), s); err != nil {
			tb.Fatalf("the seed supplied through ContractSeed failed: %v", err)
		}
	}
	if wrap != nil {
		s = wrap(tb, s)
	}
	return s
}

// dropped reports whether a path was declined through ContractWithout.
//
// Named rather than inlined because the drop set is read from two places: here,
// and by whatever registered through the seam — which reports under paths this
// file has never heard of and must answer the same question about them.
func (c *contractConfig) declined(path string) bool {
	_, ok := c.without[path]
	return ok
}

// contractPaths is every path this file reports a check under.
//
// The set a ContractWithout argument has to be a member of. Declared
// rather than observed: a check that did not run is not a check that does not
// exist — an integration-only method skips without ever consulting the drop
// set, and reading that as a phantom would fail a correct suite on a machine
// with the environment unset.
//
//nolint:gochecknoglobals // the emitted check paths, read-only after init.
var contractPaths = map[string]struct{}{}

// phantoms names every ContractWithout path that declines nothing.
//
// A drop that drops nothing is this option's silent half: the consumer wrote
// it against a check since renamed, or never emitted for that method at all,
// and every run after reads green while asserting one thing more than its
// author believes. Extensions carry their own names — the seam reports under
// paths this file has never heard of — so they count as known too.
func (c *contractConfig) phantoms() []string {
	known := func(p string) bool {
		if _, ok := contractPaths[p]; ok {
			return true
		}
		for _, e := range c.extensions {
			if e.name == p {
				return true
			}
		}
		for _, on := range c.onLookup {
			if string(suite.MethodID(contractLookup, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onFetch {
			if string(suite.MethodID(contractFetch, on.name)) == p {
				return true
			}
		}
		return false
	}
	var out []string
	for p := range c.without {
		if !known(p) {
			out = append(out, p)
		}
	}
	slices.Sort(out)
	return out
}

// run executes one check unless it was dropped, reporting the drop rather than
// silently omitting it.
func (c *contractConfig) run(t *testing.T, path, name string, fn func(tb testing.TB)) {
	t.Helper()
	if c.declined(path) {
		t.Run(name, func(t *testing.T) {
			t.Skipf("dropped through ContractWithout(%q)", path)
		})
		return
	}
	t.Run(name, func(t *testing.T) {
		t.Parallel()
		fn(t)
	})
}

